export function tr(key, values = {}, language = 'fr') {
  let text = (language === 'en' ? STR_EN[key] : undefined) ?? STR[key] ?? key;
  for (const [name, value] of Object.entries(values)) text = text.replaceAll(`{${name}}`, String(value));
  return text;
}
